import Component from 'flarum/common/Component';
import Icon from 'flarum/common/components/Icon';
import { canStart, startDiscussion } from './compose';
import { t } from '../util';

/** The phone's floating "Start a discussion". */
export default class ComposeFab extends Component {
  view() {
    if (!canStart()) return null;
    return m("button", {
      type: "button",
      className: "MastheadFab",
      onclick: startDiscussion
    }, m(Icon, {
      name: "fas fa-plus"
    }), m("span", null, t('compose')));
  }
}
flarum.reg.add('ernestdefoe-masthead', 'forum/components/ComposeFab', ComposeFab);