import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Link from 'flarum/common/components/Link';

/**
 * The masthead's title block: the logo (or a monogram tile), the forum's
 * name and the tagline.
 *
 * Drawn into core's `.Header-title`, which the server renders as a plain link
 * to the home page; mounting over it keeps the same element, the same link
 * and the same logo, and only adds what core has no slot for.
 */
export default class Brand extends Component {
  view() {
    const title = app.forum.attribute('title') || '';
    const logo = app.forum.attribute('logoUrl');
    const darkLogo = app.forum.attribute('logoDarkModeUrl');
    const tagline = app.forum.attribute('mastheadTagline');
    const showName = !logo || app.forum.attribute('mastheadShowName') !== false;
    return m(Link, {
      href: app.forum.attribute('basePath') + '/',
      id: "home-link",
      className: "MastheadBrand"
    }, logo ? m("span", {
      className: "MastheadBrand-logo"
    }, m("img", {
      src: logo,
      alt: showName ? '' : title,
      className: "Header-logo"
    }), darkLogo ? m("img", {
      src: darkLogo,
      alt: showName ? '' : title,
      className: "Header-logo Header-logo--dark-mode"
    }) : null) : m("span", {
      className: "MastheadBrand-tile",
      "aria-hidden": "true"
    }, monogram(title)), showName ? m("span", {
      className: "MastheadBrand-text"
    }, m("span", {
      className: "MastheadBrand-name"
    }, title), tagline ? m("span", {
      className: "MastheadBrand-tagline"
    }, tagline) : null) : null);
  }
}

/**
 * The admin's monogram, or the forum name's initials: "Fourth Down" → "FD".
 * Two letters at most, so the tile never overflows.
 */
function monogram(title) {
  const set = (app.forum.attribute('mastheadMonogram') || '').trim();
  if (set) return Array.from(set).slice(0, 3).join('');
  const words = title.split(/\s+/).filter(Boolean);
  const letters = words.length > 1 ? words[0][0] + words[1][0] : Array.from(title).slice(0, 2).join('');
  return letters.toUpperCase();
}
flarum.reg.add('ernestdefoe-masthead', 'forum/components/Brand', Brand);